def sorted_list_sum(lst):
    """
    Accept a list of strings, filter out those with odd lengths,
    and return the remaining strings sorted by:
      1. Length (ascending)
      2. Alphabetical order (for ties)

    The function assumes all input strings are non-empty and may contain duplicates.
    """

    def length_sort_key(s: str) -> tuple:
        return (len(s), s)

    return sorted(lst, key=length_sort_key)
