def solve(s):
    """
    Given a string s:
    - If the string contains at least one letter, reverse the case of each letter
      (lowercase becomes uppercase, and vice versa), while keeping non-letters unchanged.
    - If the string contains no letters, reverse the entire string.

    Returns the resulting string.
    """
    ans = []
    has_letter = False

    for ch in s:
        if ch.isalpha():
            has_letter = True
            ans.append(ch.swapcase())
        else:
            ans.append(ch)

    if has_letter:
        return "".join(ans)
    else:
        return s[::-1]
